Translate the following GNU C++14 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;
#define ll long long
const int mod1 = 998244353;
const int mod2 = 1e9 + 7;
const int base = 1000000;
vector<int> v[7];
int sum[7];
ll n;
ll cnt, ans;

void explore1(int level, int prefix) {
    ++cnt;
    v[level].push_back((cnt - prefix + mod1) % mod1);
    sum[level] = (sum[level] + (cnt - prefix + mod1) % mod1) % mod2;
    if (level == 6) return;
    for (int digit = 0; digit < 10; ++digit)
        explore1(level + 1, prefix * 10 + digit);
}

void explore2(ll x) {
    if (x > n) return;
    if (x * base + base - 1 <= n && x * base * 10 > n) {
        ll currentCount = cnt;
        for (int i = 0, multiplier = 1; i <= 6; ++i, multiplier *= 10) {
            int size = v[i].size();
            int difference = ((currentCount - x * multiplier) % mod1 + mod1) % mod1;
            int position = lower_bound(v[i].begin(), v[i].end(), mod1 - difference) - v[i].begin();
            ans = (ans + 1ll * difference * size + sum[i]) % mod2;
            ans = (ans - 1ll * mod1 * (size - position) % mod2 + mod2) % mod2;
            cnt += size;
        }
        return;
    }
    ++cnt;
    ans = (ans + ((cnt - x) % mod1 + mod1) % mod1) % mod2;
    for (int digit = 0; digit <= 9; ++digit) explore2(x * 10 + digit);
}

int main() {
    scanf("%lld", &n);
    explore1(0, 0);
    for (int i = 0; i <= 6; ++i) sort(v[i].begin(), v[i].end());
    cnt = 0;
    for (int i = 1; i <= 9; ++i) explore2(i);
    printf("%lld\n", ans);
    return 0;
}
</original_code>
